def optimize_bess_plan(ctx):
    bess = ctx["bess"]
    price = ctx["forecast"]["price_jpy_kwh"]["p50"]
    p90 = ctx["forecast"]["price_jpy_kwh"]["p90"]
    rm = ctx["forecast"].get("reserve_margin_p50", [0.2] * SLOTS)

    eff_price = [
        p90[t] if rm[t] < 0.08 else (price[t] * 0.7 + p90[t] * 0.3 if rm[t] < 0.12 else price[t])
        for t in range(SLOTS)
    ]

    rte = bess.get("rte", bess.get("eta_charge", 0.92) * bess.get("eta_discharge", 0.92))
    deg = bess.get("degradation_jpy_per_mwh", 8000.0) / 1000.0

    def eval_plan(p):
        prof = 0.0
        for t in range(SLOTS):
            mw = p[t]
            if mw > 0:
                prof += mw * 0.5 * (eff_price[t] - deg)
            elif mw < 0:
                prof += mw * 0.5 * eff_price[t]
        return prof

    plan = [0.0] * SLOTS
    for step in [30.0, 10.0, 2.5]:
        for _ in range(15):
            best_pair = None
            best_gain = 0.0

            candidates = []
            for t_ch in range(SLOTS):
                for t_dis in range(SLOTS):
                    if t_ch == t_dis:
                        continue
                    spread = eff_price[t_dis] * rte - eff_price[t_ch] - deg * rte
                    if spread > 0.1:
                        candidates.append((spread, t_ch, t_dis))

            candidates.sort(reverse=True, key=lambda x: x[0])
            curr_clipped = clip_plan(plan, bess["soc_mwh"], bess)
            curr_val = eval_plan(curr_clipped)

            for _, t_ch, t_dis in candidates[:20]:
                test_plan = list(plan)
                test_plan[t_ch] -= step
                test_plan[t_dis] += step

                clipped = clip_plan(test_plan, bess["soc_mwh"], bess)
                gain = eval_plan(clipped) - curr_val
                if gain > best_gain + 1e-4:
                    best_gain = gain
                    best_pair = (t_ch, t_dis)

            if best_pair is None:
                break

            t_ch, t_dis = best_pair
            plan[t_ch] -= step
            plan[t_dis] += step

    return clip_plan(plan, bess["soc_mwh"], bess)


