def plan_day_ahead(ctx):
    """Value-stacking BESS dispatch with chronological constraints + terminal SOC valuation and full DA bidding."""
    bess, rules = ctx["bess"], ctx["rules"]
    price = ctx["forecast"]["price_jpy_kwh"]["p50"]
    net = ctx["forecast"]["net_load_mwh_p50"]
    soc0 = bess["soc_mwh"]
    deg_cost_kwh = bess["degradation_jpy_per_mwh"] / 1000.0
    mean_p = sum(price) / SLOTS

    def eval_plan(raw_plan):
        clipped = clip_plan(raw_plan, soc0, bess)
        soc = soc0
        val = 0.0
        for t in range(SLOTS):
            mw = clipped[t]
            val += mw * 0.5 * price[t]
            if mw > 0:
                val -= mw * 0.5 * deg_cost_kwh
            soc = soc_after(soc, mw, bess)
        val += (soc - soc0) * mean_p
        return val, clipped

    plan = [0.0] * SLOTS
    cur_val, plan = eval_plan(plan)

    for step_mw in [20.0, 10.0, 5.0, 2.5]:
        improved = True
        while improved:
            improved = False
            best_val = cur_val
            best_op = None

            for t in range(SLOTS):
                cand = list(plan)
                cand[t] -= step_mw
                v, _ = eval_plan(cand)
                if v > best_val + 1e-4:
                    best_val = v
                    best_op = ("single", t, -step_mw)

                cand = list(plan)
                cand[t] += step_mw
                v, _ = eval_plan(cand)
                if v > best_val + 1e-4:
                    best_val = v
                    best_op = ("single", t, step_mw)

            for c in range(SLOTS):
                for d in range(SLOTS):
                    if c == d:
                        continue
                    if price[d] * bess["rte"] - price[c] < deg_cost_kwh * 0.3:
                        continue
                    cand = list(plan)
                    cand[c] -= step_mw
                    cand[d] += step_mw
                    v, _ = eval_plan(cand)
                    if v > best_val + 1e-4:
                        best_val = v
                        best_op = ("pair", c, d)

            if best_op is not None:
                if best_op[0] == "single":
                    _, t, delta = best_op
                    plan[t] += delta
                else:
                    _, c, d = best_op
                    plan[c] -= step_mw
                    plan[d] += step_mw
                cur_val, plan = eval_plan(plan)
                improved = True

    plan = clip_plan(plan, soc0, bess)
    bids = []
    for t in range(SLOTS):
        qty = net[t] - plan[t] * 0.5
        if qty > 0:
            bids.append({
                "slot": t + 1,
                "side": "buy",
                "qty_mwh": lots(qty, rules),
                "limit_jpy_kwh": rules["price_cap"],
            })
        elif qty < -0.01:
            bids.append({
                "slot": t + 1,
                "side": "sell",
                "qty_mwh": lots(-qty, rules),
                "limit_jpy_kwh": rules["price_floor"],
            })

    return {"bids": bids, "bess_plan_mw": plan}


